FJ=true
end
end
local IJ=not FJ and kJ.inventory:get_item_by_uuid(rJ.u._equipped_relic)
if IJ then
table.insert(AJ,{it=IJ,w=db.relicWorth(rJ.u,IJ)*tJ*100})
