for yM,zM in ipairs(db.foodHeld())do
local AM=zM.xp*tM
local BM=math.min(zM.n,math.floor((uM-wM)/math.max(1,AM)))
if BM>0 then
vM[zM.id]=BM
wM=wM+BM*AM
xM=xM+BM
end
end
if xM==0 then
J.str.feedNote=pM.name..utc[2067]
