while M.now()-GM<4 and(tonumber((qM.collection:get_unit_by_uuid(pM.uuid)or rM).xp)or 0)<=CM do
task.wait(0.25)
end
local HM=qM.collection:get_unit_by_uuid(pM.uuid)or rM
local IM=(tonumber(HM.xp)or 0)-CM
if IM>0 then
R.add(string.format(utc[2069],xM,pM.name),xM,utc[2070],string.format(utc[2071],M.fmt(IM),DM,db.level(HM)))
db.note(string.format(utc[2072],pM.name,xM,M.fmt(IM),DM,db.level(HM),math.abs(IM-wM)>wM*0.1 and string.format(utc[2073],M.fmt(wM))or utc[365]))
else
db.note(string.format(utc[2074],pM.name,tostring(EM and FM or utc[1700])))
j.backoff(utc[2057],600)
end
elseif pM.kind==utc[2062]then
P.fuseInto(pM.uuid,false)
end
end
