local gnb,hnb={},0
for inb,jnb in pairs(fnb.profile_data.collection.owned_units)do
local knb=jnb.unit_id
if not gnb[knb]and H.Units[knb]and not N.isFarm(knb)and N.rows(knb)and not N.hidden(knb)then
local lnb,mnb=pcall(H.USC.calculate_level,knb,tonumber(jnb.xp)or 0)
if lnb and(tonumber(mnb)or 0)>=W.GROWN_LEVEL then
gnb[knb]=true
