local vnb=pnb.collection:get_unit_by_uuid(unb.uuid)or unb
local wnb,xnb=pcall(H.USC.calculate_level,vnb.unit_id,tonumber(vnb.xp)or 0)
local ynb=N.isFarm(vnb.unit_id)or not snb or(wnb and(tonumber(xnb)or 0)>=W.GROWN_LEVEL)
if H.Units[vnb.unit_id]and N.rows(vnb.unit_id)and not N.hidden(vnb.unit_id)and ynb then
local znb=N.isFarm(vnb.unit_id)
local Anb,Bnb=pcall(znb and function()
return N.farm(vnb,N.rows(vnb.unit_id).max)
end or N.score,vnb,nnb)
Bnb=(Anb and Bnb or 0)*(znb and 1 or N.skinMul(vnb,onb and onb.skinSet))
local Cnb=znb and rnb or qnb
if not Cnb[vnb.unit_id]or Bnb>Cnb[vnb.unit_id].sc then
Cnb[vnb.unit_id]={u=vnb,sc=Bnb}
end
end
end
local Dnb,Enb={},{}
for Fnb,Gnb in pairs(qnb)do
table.insert(Dnb,Gnb)
end
for Hnb,Inb in pairs(rnb)do
table.insert(Enb,Inb)
end
table.sort(Dnb,function(Jnb,Knb)
return Jnb.sc>Knb.sc
end)
table.sort(Enb,function(Lnb,Mnb)
return Lnb.sc>Mnb.sc
