end
end
end
for Unb=1,math.min(4,#Pnb)do
table.insert(Nnb,Pnb[Unb])
end
for Vnb=1,math.min(2,#Qnb)do
table.insert(Nnb,Qnb[Vnb])
end
for Wnb=1,math.min(3,#Enb)do
table.insert(Nnb,Enb[Wnb].u)
end
local Xnb={}
for Ynb=11,#Dnb do
local Znb=N.rows(Dnb[Ynb].u.unit_id)[0]
local _nb=Znb and Znb.atk and N.attackInfo(Znb.atk,Znb.range)
if _nb and(_nb.slowTime>0 or _nb.stun>0)then
table.insert(Xnb,Dnb[Ynb].u)
end
end
for aob=1,math.min(3,#Xnb)do
table.insert(Nnb,Xnb[aob])
end
if onb and((onb.flyChance or 0)>0 or onb.mapFly or(onb.shield or 0)>0)then
local bob,cob={},{}
for dob=11,#Dnb do
local eob=Dnb[dob].u
