if N.airFrom(eob.unit_id)==0 then
table.insert(bob,eob)
end
local gob,hob=tonumber(fob and fob.cd)or 0,tonumber((H.Units[eob.unit_id]or{}).cost)or 0
if gob>0 and hob>0 and N.range(eob,0)>=15 then
local iob=N.attackInfo(fob.atk,fob.range)
table.insert(cob,{u=eob,v=iob.n*iob.hits/gob/hob*math.min(6,N.cap(eob))})
end
end
table.sort(cob,function(job,kob)
return job.v>kob.v
end)
for lob=1,math.min(4,#bob)do
table.insert(Nnb,bob[lob])
end
for mob=1,math.min(6,#cob)do
table.insert(Nnb,cob[mob].u)
end
end
local nob,oob={},{}
for pob,qob in ipairs(Nnb)do
if not nob[qob]then
nob[qob]=true
table.insert(oob,qob)
end
end
oob.rest={}
for rob,sob in ipairs(Dnb)do
if not nob[sob.u]then
table.insert(oob.rest,sob.u)
end
end
return oob
end
function W.objective(tob)
