return utc[1805]
end
if pwb._finished then
return utc[2731]
end
local qwb=cb.screens(pwb)[1]
if qwb then
if qwb.t==cb.T.SHOP then
return utc[2092],qwb
end
if qwb.t==cb.T.OPEN then
return utc[2732],qwb
end
if qwb.t==cb.T.SHRINE then
return utc[2682],qwb
end
return utc[2733],qwb
end
return utc[2734]
end
function cb.logState(rwb,swb)
local twb={}
for uwb,vwb in pairs(rwb)do
if not cb.KNOWN[uwb]and not(type(vwb)==utc[1436]and next(vwb)==nil)then
table.insert(twb,tostring(uwb))
end
end
