local wwb={}
for xwb,ywb in ipairs(cb.screens(rwb))do
table.insert(wwb,tostring(ywb.t))
end
local zwb=table.concat(twb,utc[2033])..(#wwb>0 and(utc[1535]..table.concat(wwb,utc[2033]))or utc[365])
if zwb==utc[365]or J.dg.seen[zwb]then
return
end
J.dg.seen[zwb]=os.time()
local Awb={}
for Bwb,Cwb in ipairs(twb)do
local Dwb=rwb[Cwb]
table.insert(Awb,Cwb..utc[2478]..(type(Dwb)==utc[1436]and M.json(M.plain(Dwb)):sub(1,500)or tostring(Dwb)))
