function cb.offers(Fwb,Gwb)
local Hwb={}
if type(Fwb)~=utc[1436]then
return Hwb
end
for Iwb,Jwb in pairs(Fwb)do
local Kwb,Lwb
if type(Jwb)==utc[1436]then
Kwb=Jwb.id or Jwb.item_id or Jwb.item
Lwb=tonumber(Jwb.cost)or tonumber(Jwb.price)
elseif type(Jwb)==utc[1438]then
Kwb=Jwb
elseif cb.item(Iwb)then
Kwb=Iwb
Lwb=tonumber(Jwb)
end
if type(Kwb)==utc[1438]and cb.item(Kwb)then
table.insert(Hwb,{key=Iwb,id=Kwb,cost=Lwb or tonumber(cb.item(Kwb).cost)or 0,bought=type(Jwb)==utc[1436]and(Jwb.bought or Jwb.sold or Jwb.purchased)or nil})
