function cb.shopAhead(Wwb)
for Xwb,Ywb in ipairs(cb.rooms(Wwb))do
if Ywb.tags[cb.T.SHOP]then
return true
end
for Zwb,_wb in ipairs(cb.after(Wwb,Ywb.choice))do
if _wb.tags[cb.T.SHOP]then
return true
end
end
end
return false
end
cb.LUCK_RESERVE=500
cb.MIN_WORTH=0.02
cb.TOP_WORTH=0.08
function cb.shop(axb,bxb)
local cxb=cb.cleared(axb)
local dxb=cb.res(axb)
local exb=1+0.1*(cb.items(axb)._curse_shop or 0)
local fxb=cb.shopAhead(axb)and math.ceil(cb.LUCK_RESERVE*exb)or 0
local gxb={}
local hxb,ixb={},0
for jxb,kxb in ipairs(cb.offers(bxb and bxb.data))do
kxb.cost=math.ceil(kxb.cost*exb)
table.insert(hxb,tostring(cb.item(kxb.id).name or kxb.id))
if not kxb.bought and not cb.isCurse(kxb.id)then
kxb.luck=tonumber(cb.item(kxb.id).luck_increase)~=nil
kxb.v=cb.itemValue(kxb.id,axb)
if not kxb.luck and kxb.v/math.max(1,kxb.cost)<cb.MIN_WORTH then
ixb=ixb+1
elseif kxb.v>0 and(kxb.luck or cxb>=10 or kxb.v/math.max(1,kxb.cost)>=cb.TOP_WORTH)then
table.insert(gxb,kxb)
end
end
end
table.sort(gxb,function(lxb,mxb)
if lxb.luck~=mxb.luck then
return lxb.luck
end
return lxb.v/math.max(1,lxb.cost)>mxb.v/math.max(1,mxb.cost)
end)
local nxb,oxb,pxb={},0,0
for qxb,rxb in ipairs(gxb)do
if rxb.cost<=dxb-(rxb.luck and 0 or fxb)then
if cb.buy(rxb)then
dxb=cb.res(cb.data())
table.insert(nxb,string.format(utc[2741],tostring(cb.item(rxb.id).name or rxb.id),rxb.cost))
end
elseif rxb.cost<=dxb then
pxb=pxb+1
else
oxb=oxb+1
end
end
cb.note(string.format(utc[2742],cxb,#hxb>0 and table.concat(hxb,utc[1532])or utc[2743],#nxb>0 and(utc[2744]..table.concat(nxb,utc[1532]))or(cxb<10 and utc[2745]or(pxb>0 and utc[2746]or utc[2747])),dxb,oxb>0 and string.format(utc[2748],oxb)or utc[365],pxb>0 and string.format(utc[2749],pxb,fxb)or utc[365],ixb>0 and string.format(utc[2750],ixb)or utc[365]))
j.request(utc[2751],utc[2752])
end
function cb.shrine(sxb,txb)
