function cb.wallet()
local Fxb=H.session()and H.session().profile_data or{}
local Gxb=Fxb.inventory or{}
local Hxb={gems=tonumber(H.cur(utc[1496]))or 0,gold=tonumber(H.cur(utc[1498]))or 0,items={},units={},unique=0}
