Hxb.units[Kxb]=Lxb.unit_id
end
for Mxb in pairs(Gxb.unique_items or{})do
Hxb.unique=Hxb.unique+1
end
return Hxb
end
function cb.walletDiff(Nxb,Oxb)
local Pxb={}
if Oxb.gems~=Nxb.gems then
table.insert(Pxb,string.format(utc[2759],Oxb.gems-Nxb.gems))
end
if Oxb.gold~=Nxb.gold then
table.insert(Pxb,string.format(utc[2760],Oxb.gold-Nxb.gold))
end
for Qxb,Rxb in pairs(Oxb.items)do
if Rxb~=(Nxb.items[Qxb]or 0)then
table.insert(Pxb,string.format(utc[2761],Rxb-(Nxb.items[Qxb]or 0),tostring(Qxb)))
end
end
for Sxb,Txb in pairs(Oxb.units)do
if not Nxb.units[Sxb]then
table.insert(Pxb,utc[2762]..N.name(Txb))
end
end
if Oxb.unique~=Nxb.unique then
table.insert(Pxb,string.format(utc[2763],Oxb.unique-Nxb.unique))
end
return#Pxb>0 and table.concat(Pxb,utc[1532])or utc[2764]
end
