cb.note(string.format(utc[2770],ayb,byb,Vxb and utc[2771]or(Zxb<=1 and utc[2772]or utc[2773]),cb.luck(Uxb),(tonumber(H.cur(utc[1496]))or 0)-dyb))
local xyb,yyb,zyb=cb.res(cb.data())
if(Vxb or _xb>=cb.ROOMS)and yyb+zyb>0 then
